        let denominator_scale = -quotient * reciprocal;
        let derivative_scale = 2.0 * source_value * denominator_scale;
        self.v[index] = quotient;
        for axis in 0..NODE_COUNT { self.dn[index][axis] = source_dn[axis] * derivative_scale; }
